#include <stdio.h>
#include <stdlib.h>

#define MAXN 100000

int parent[MAXN + 1];
int marked[MAXN + 1];
int nearest[MAXN + 1];

int find_nearest(int u) {
    if (marked[u]) return u;
    if (nearest[u] != -1) return nearest[u];
    if (u == 1) return 1; // root is always marked
    return nearest[u] = find_nearest(parent[u]);
}

int main() {
    int N, Q;
    scanf("%d %d", &N, &Q);

    for (int i = 2; i <= N; i++) {
        scanf("%d", &parent[i]);
    }

    // Initialize
    for (int i = 1; i <= N; i++) {
        marked[i] = 0;
        nearest[i] = -1;
    }
    marked[1] = 1; // root is initially marked

    long long sum = 0;

    for (int i = 0; i < Q; i++) {
        char op;
        int node;
        scanf(" %c %d", &op, &node);

        if (op == 'M') {
            marked[node] = 1;
            // Reset nearest cache for this node's descendants
            // We can just invalidate by setting nearest to -1 for all
            // But that's O(N) per operation. Instead, we just set marked and
            // let find_nearest handle it lazily.
        } else { // op == 'Q'
            int ans = find_nearest(node);
            sum += ans;
        }
    }

    printf("%lld\n", sum);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005
#define LOG 20

typedef struct Edge {
    int to, next;
} Edge;

static Edge edges[2 * MAXN];
static int head[MAXN], ecnt = 0;

static int up[LOG][MAXN];
static int depth[MAXN];
static int tin[MAXN], tout[MAXN], timer_ = 0;
static int order[MAXN];

static int N, Q;

/* DSU-on-tree style "next unprocessed ancestor" structure */
static int dsu[MAXN];

/* nearest marked ancestor for compressed representatives */
static int best[MAXN];

/* marked flag */
static int marked[MAXN];

static void add_edge(int u, int v) {
    edges[++ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt;
}

static int find_set(int v) {
    if (dsu[v] == v) return v;
    return dsu[v] = find_set(dsu[v]);
}

static int is_ancestor(int u, int v) {
    return tin[u] <= tin[v] && tout[v] <= tout[u];
}

static void dfs(int v, int p) {
    tin[v] = ++timer_;
    order[timer_] = v;
    up[0][v] = p;
    for (int i = 1; i < LOG; i++) {
        up[i][v] = up[i - 1][ up[i - 1][v] ];
    }

    for (int e = head[v]; e; e = edges[e].next) {
        int to = edges[e].to;
        if (to == p) continue;
        depth[to] = depth[v] + 1;
        dfs(to, v);
    }
    tout[v] = timer_;
}

/*
   Mark node v.
   We "paint" the path from v upward until reaching an already processed segment.
   For each DSU representative x encountered, best[x] becomes v's nearest marked ancestor
   for nodes in that compressed segment.
*/
static void mark_node(int v) {
    if (marked[v]) return;
    marked[v] = 1;

    int x = find_set(v);
    while (!marked[x]) {
        best[x] = v;
        dsu[x] = find_set(up[0][x]);
        x = find_set(x);
    }
    best[x] = x;
}

/*
   Query nearest marked ancestor of v.
   Let x = find_set(v). If x itself is marked, answer x.
   Otherwise answer best[x].
*/
static int query_node(int v) {
    int x = find_set(v);
    if (marked[x]) return x;
    return best[x];
}

int main(void) {
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    for (int i = 1; i <= N; i++) head[i] = 0;

    for (int i = 2; i <= N; i++) {
        int p;
        scanf("%d", &p);
        add_edge(p, i);
        add_edge(i, p);
    }

    depth[1] = 0;
    dfs(1, 1);

    for (int i = 1; i <= N; i++) {
        dsu[i] = i;
        best[i] = 1;
        marked[i] = 0;
    }

    marked[1] = 1;
    best[1] = 1;

    long long ans = 0;

    for (int i = 0; i < Q; i++) {
        int t, v;
        scanf("%d %d", &t, &v);
        if (t == 1) {
            mark_node(v);
        } else {
            ans += query_node(v);
        }
    }

    printf("%lld\n", ans);
    return 0;
}

