const int MAXN = 500005;
const int LOG = 19; // since 2^19 = 524288 > 500000

vector<int> adj[MAXN];
int up[MAXN][LOG];
int depth[MAXN];
bool marked[MAXN];

void dfs(int v, int p) {
    up[v][0] = p;
    for (int i = 1; i < LOG; i++) {
        if (up[v][i-1] != -1)
            up[v][i] = up[up[v][i-1]][i-1];
        else
            up[v][i] = -1;
    }
    for (int u : adj[v]) {
        if (u != p) {
            depth[u] = depth[v] + 1;
            dfs(u, v);
        }
    }
}

int query(int v) {
    if (marked[v]) return v;
    for (int i = LOG-1; i >= 0; i--) {
        if (up[v][i] != -1 && !marked[up[v][i]]) {
            v = up[v][i];
        }
    }
    // now either parent is marked or we are at root's child
    return up[v][0];
}

