#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<vector<int>> g(N + 1);
    for (int i = 2; i <= N; ++i) {
        int p;
        cin >> p;
        g[p].push_back(i);
    }

    vector<int> tin(N + 1), tout(N + 1), depth(N + 1), parent(N + 1);
    int timer = 0;

    // Iterative DFS for Euler tour
    vector<pair<int,int>> st;
    st.push_back({1, 0});
    parent[1] = 0;
    depth[1] = 0;

    while (!st.empty()) {
        auto &[v, idx] = st.back();
        if (idx == 0) tin[v] = ++timer;

        if (idx < (int)g[v].size()) {
            int to = g[v][idx++];
            parent[to] = v;
            depth[to] = depth[v] + 1;
            st.push_back({to, 0});
        } else {
            tout[v] = timer;
            st.pop_back();
        }
    }

    int B = max(1, (int)sqrt(N) + 1);
    vector<int> marked(N + 1, 0);
    marked[1] = 1;

    vector<int> jump(N + 1);
    for (int v = 1; v <= N; ++v) jump[v] = 1; // initially root is nearest marked ancestor for all

    auto rebuild = [&]() {
        for (int v = 1; v <= N; ++v) {
            if (marked[v]) {
                jump[v] = v;
            } else {
                jump[v] = jump[parent[v]];
            }
        }
    };

    vector<int> buffer;
    long long ans = 0;

    auto isAncestor = [&](int u, int v) {
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    };

    for (int i = 0; i < Q; ++i) {
        int type, v;
        cin >> type >> v;

        if (type == 1) {
            buffer.push_back(v);
            marked[v] = 1;
            if ((int)buffer.size() >= B) {
                rebuild();
                buffer.clear();
            }
        } else {
            int res = jump[v];
            for (int x : buffer) {
                if (isAncestor(x, v) && depth[x] > depth[res]) {
                    res = x;
                }
            }
            ans += res;
        }
    }

    cout << ans << '\n';
    return 0;
}

