import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N, Q;
    static ArrayList<Integer>[] tree;
    static int[] parent, depth, heavy, head, pos, size;
    static int curPos = 0;

    static int[] seg;

    static void dfs1(int u) {
        size[u] = 1;
        int maxSub = 0;
        for (int v : tree[u]) {
            depth[v] = depth[u] + 1;
            dfs1(v);
            size[u] += size[v];
            if (size[v] > maxSub) {
                maxSub = size[v];
                heavy[u] = v;
            }
        }
    }

    static void dfs2(int u, int h) {
        head[u] = h;
        pos[u] = ++curPos;
        if (heavy[u] != 0) dfs2(heavy[u], h);
        for (int v : tree[u]) {
            if (v != heavy[u]) dfs2(v, v);
        }
    }

    static void update(int idx, int l, int r, int p, int val) {
        if (l == r) {
            seg[idx] = val;
            return;
        }
        int mid = (l + r) >>> 1;
        if (p <= mid) update(idx << 1, l, mid, p, val);
        else update(idx << 1 | 1, mid + 1, r, p, val);
        seg[idx] = Math.max(seg[idx << 1], seg[idx << 1 | 1]);
    }

    static int queryMax(int idx, int l, int r, int ql, int qr) {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return seg[idx];
        int mid = (l + r) >>> 1;
        return Math.max(
                queryMax(idx << 1, l, mid, ql, qr),
                queryMax(idx << 1 | 1, mid + 1, r, ql, qr)
        );
    }

    static int queryNearestMarkedAncestor(int u) {
        int bestPos = 0;
        while (u != 0) {
            int h = head[u];
            int cur = queryMax(1, 1, N, pos[h], pos[u]);
            if (cur > bestPos) bestPos = cur;
            u = parent[h];
        }
        return bestPos == 0 ? 1 : nodeAtPos[bestPos];
    }

    static int[] nodeAtPos;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        Q = fs.nextInt();

        tree = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) tree[i] = new ArrayList<>();

        parent = new int[N + 1];
        depth = new int[N + 1];
        heavy = new int[N + 1];
        head = new int[N + 1];
        pos = new int[N + 1];
        size = new int[N + 1];
        nodeAtPos = new int[N + 1];

        for (int i = 2; i <= N; i++) {
            parent[i] = fs.nextInt();
            tree[parent[i]].add(i);
        }

        dfs1(1);
        dfs2(1, 1);

        for (int i = 1; i <= N; i++) nodeAtPos[pos[i]] = i;

        seg = new int[4 * (N + 5)];

        // Initially root is marked
        update(1, 1, N, pos[1], pos[1]);

        long ans = 0;

        for (int i = 0; i < Q; i++) {
            int type = fs.nextInt();
            int v = fs.nextInt();

            if (type == 1) {
                update(1, 1, N, pos[v], pos[v]);
            } else {
                ans += queryNearestMarkedAncestor(v);
            }
        }

        System.out.println(ans);
    }
}
